import { httpClient } from "@/lib/http-client";

export async function fetchProfile(userId: string) {
  const response = await fetch(`${process.env.PROFILE_API}/profiles/${userId}`);
  if (!response.ok) {
    throw new Error(`profile ${userId}: ${response.status}`);
  }
  return response.json();
}

export async function fetchSettings(userId: string) {
  return httpClient.get(`/settings/${userId}`);
}
